css:
@page { size: A4 portrait; margin: 16mm; }
.soa { font-family: Helvetica, Arial, sans-serif; color: #000; font-size: 9pt; }
.soa table { width: 100%; border-collapse: collapse; }
.soa td, .soa th { vertical-align: top; }
.soa .l { text-align: left; }
.soa .c { text-align: center; }
.soa .r { text-align: right; }
.soa .b { font-weight: bold; }

.soa-header { border-bottom: 1.5pt solid #000; }
.soa-header td { padding-bottom: 10pt; }
.soa-header-right { text-align: right; vertical-align: bottom !important; }
.soa-monogram { width: 18mm; height: 18mm; line-height: 18mm; border: 1.4pt solid #000; text-align: center; font-weight: bold; font-size: 16pt; margin-bottom: 6pt; }
.soa-logo-img { max-height: 18mm; max-width: 50mm; margin-bottom: 6pt; }
.soa-company-name { font-weight: bold; font-size: 15pt; }
.soa-address { font-size: 8.5pt; color: #444; line-height: 1.45; margin-top: 2pt; }
.soa-title { font-weight: bold; font-size: 17pt; letter-spacing: 0.5pt; }
.soa-subtitle { font-size: 9pt; color: #444; margin-top: 2pt; }

.soa-info td { padding: 14pt 0; }
.soa-customer { width: 60%; }
.soa-summary { text-align: right; }
.soa-label { font-weight: bold; font-size: 8pt; color: #777; letter-spacing: 0.5pt; }
.soa-customer .soa-label { border-bottom: 0.5pt solid #BBB; padding-bottom: 3pt; margin-bottom: 6pt; display: inline-block; min-width: 60%; }
.soa-label-gap { margin-top: 10pt; }
.soa-customer-name { font-weight: bold; font-size: 12pt; margin-bottom: 3pt; }
.soa-detail { font-size: 9pt; color: #444; line-height: 1.45; }
.soa-statement-date { font-weight: bold; font-size: 11pt; margin-top: 2pt; }
.soa-total-outstanding { font-weight: bold; font-size: 18pt; margin-top: 2pt; }

.soa-items { border: 1.2pt solid #000; table-layout: fixed; }
.soa-items th, .soa-items td { border: 0.5pt solid #BBB; padding: 12pt 6pt; }
.soa-items thead th { background: #F2F2F2; font-weight: bold; font-size: 8.5pt; border-top: 1.2pt solid #000; border-bottom: 1.2pt solid #000; }
.soa-items tbody td { font-size: 9.5pt; }
.soa-items tr.soa-total td { background: #F2F2F2; font-weight: bold; font-size: 9.5pt; border-top: 1.2pt solid #000; border-bottom: 1.2pt solid #000; }
.soa-items tr { page-break-inside: avoid; }
.soa-items thead { display: table-header-group; }
.soa-items th, .soa-items tr.soa-total td { -webkit-print-color-adjust: exact; print-color-adjust: exact; }

.soa-signature { width: 55mm; margin: 40pt 0 0 auto; text-align: center; page-break-inside: avoid; }
.soa-signature-line { border-top: 0.75pt solid #000; margin-bottom: 4pt; }
.soa-signature-title { font-weight: bold; font-size: 9pt; }
.soa-signature-subtitle { font-size: 8.5pt; color: #444; }

.soa-footer { border-top: 1pt solid #000; margin-top: 24pt; }
.soa-footer td { font-size: 8pt; color: #444; padding-top: 5pt; }
